<script setup>
import {computed,ref} from 'vue';
import {useAccess} from '../composables/access.js';
import {accessError} from '../services/access-errors.js';
import AppIcon from './AppIcon.vue';
import {normalizePassword} from '../../../shared/access-passwords.js';
const {session,login,setupMaster,refresh,error:sessionError}=useAccess();
const username=ref(''),password=ref(''),repeat=ref(''),busy=ref(false),error=ref('');
const setup=computed(()=>session.value?.master_setup_required===true);
async function enter(){if(busy.value)return;error.value='';if(setup.value&&normalizePassword(password.value)!==normalizePassword(repeat.value)){error.value='Les contrasenyes no coincideixen.';return;}busy.value=true;try{if(setup.value)await setupMaster(password.value);else await login(username.value,password.value);password.value='';repeat.value='';}catch(cause){error.value=accessError(cause)||'No s’ha pogut iniciar sessió.';password.value='';repeat.value='';}finally{busy.value=false;}}
</script>
<template><main class="login-page"><section class="panel login-card"><div class="login-brand"><span class="brand-mark"><AppIcon name="book" /></span><strong>Comptabilitat</strong></div><h1>{{ setup?'Configurar el màster':'Iniciar sessió' }}</h1><p class="muted">{{ setup?'Defineix la contrasenya del màster per començar.':'Entra amb el teu usuari i contrasenya.' }}</p><p v-if="error||sessionError" class="notice error-notice" role="alert">{{ error||sessionError }}<button v-if="sessionError" class="button" type="button" @click="refresh">Tornar a provar</button></p><form class="access-form" @submit.prevent="enter"><label v-if="!setup">Usuari<input v-model="username" name="username" autocomplete="username" maxlength="80" autofocus required :disabled="busy"></label><p v-else>Usuari: <strong>administrador</strong></p><label>{{ setup?'Contrasenya nova':'Contrasenya' }}<input v-model="password" name="password" type="password" :autocomplete="setup?'new-password':'current-password'" :minlength="setup?1:undefined" maxlength="128" required :disabled="busy"></label><label v-if="setup">Repetir contrasenya<input v-model="repeat" name="password_repeat" type="password" autocomplete="new-password" minlength="1" maxlength="128" required :disabled="busy"></label><button class="button primary" :disabled="busy">{{ busy?'Entrant…':setup?'Crear contrasenya i entrar':'Entrar' }}</button></form><p class="login-help muted">L’usuari i la contrasenya no distingeixen majúscules i minúscules.<template v-if="!setup"> Per activar-ho en una contrasenya antiga, entra una vegada amb l’escriptura original.</template></p><p v-if="!setup" class="login-help muted">El màster entra amb l’usuari <strong>administrador</strong> i la seva contrasenya actual.</p></section></main></template>
